create schema if not exists private;
revoke all on schema private from public, anon;
grant usage on schema private to authenticated;
create table if not exists private.admin_users (user_id uuid primary key references auth.users(id) on delete cascade, role text not null check (role in ('owner','moderator','support')), granted_by uuid references auth.users(id) on delete set null, created_at timestamptz not null default now());
alter table private.admin_users enable row level security;
revoke all on private.admin_users from public, anon, authenticated, service_role;
create table if not exists private.admin_audit_log (id uuid primary key default gen_random_uuid(), actor_id uuid references auth.users(id) on delete set null, action text not null, target_type text not null, target_id uuid, details jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create index if not exists admin_audit_log_created_at_idx on private.admin_audit_log (created_at desc);
alter table private.admin_audit_log enable row level security;
revoke all on private.admin_audit_log from public, anon, authenticated, service_role;
create or replace function private.is_admin() returns boolean language sql stable security definer set search_path = pg_catalog, private as $$ select exists (select 1 from private.admin_users a where a.user_id = auth.uid() and a.role in ('owner','moderator','support')); $$;
create or replace function private.can_review_reports() returns boolean language sql stable security definer set search_path = pg_catalog, private as $$ select exists (select 1 from private.admin_users a where a.user_id = auth.uid() and a.role in ('owner','moderator')); $$;
revoke all on function private.is_admin() from public, anon;
revoke all on function private.can_review_reports() from public, anon;
grant execute on function private.is_admin() to authenticated;
grant execute on function private.can_review_reports() to authenticated;
drop policy if exists "Administrators view all profiles" on public.profiles;
create policy "Administrators view all profiles" on public.profiles for select to authenticated using ((select private.is_admin()));
drop policy if exists "Administrators view reports" on public.reports;
create policy "Administrators view reports" on public.reports for select to authenticated using ((select private.can_review_reports()));
drop policy if exists "Moderators update report status" on public.reports;
create policy "Moderators update report status" on public.reports for update to authenticated using ((select private.can_review_reports())) with check ((select private.can_review_reports()));
grant select on public.reports to authenticated;
grant update (status) on public.reports to authenticated;
alter table public.reports add constraint reports_status_allowed check (status in ('new','reviewing','resolved','dismissed'));
create or replace function private.audit_report_status_change() returns trigger language plpgsql security definer set search_path = pg_catalog, private as $$ begin if old.status is distinct from new.status then insert into private.admin_audit_log (actor_id,action,target_type,target_id,details) values (auth.uid(),'report_status_changed','report',new.id,jsonb_build_object('from',old.status,'to',new.status)); end if; return new; end; $$;
revoke all on function private.audit_report_status_change() from public, anon, authenticated;
drop trigger if exists audit_report_status_change on public.reports;
create trigger audit_report_status_change after update of status on public.reports for each row execute function private.audit_report_status_change();
create or replace function private.admin_overview() returns jsonb language plpgsql stable security definer set search_path = pg_catalog, private, public as $$ declare result jsonb; begin if not private.is_admin() then raise exception 'Administrator access required' using errcode = '42501'; end if; select jsonb_build_object('members_total',(select count(*) from public.profiles),'discoverable_profiles',(select count(*) from public.profiles where is_discoverable),'follows_total',(select count(*) from public.follows),'reports_total',(select count(*) from public.reports),'reports_new',(select count(*) from public.reports where status='new'),'reports_reviewing',(select count(*) from public.reports where status='reviewing'),'reports_resolved',(select count(*) from public.reports where status='resolved'),'reports_dismissed',(select count(*) from public.reports where status='dismissed')) into result; return result; end; $$;
create or replace function private.admin_recent_activity(p_limit integer default 20) returns table (id uuid,actor_id uuid,action text,target_type text,target_id uuid,details jsonb,created_at timestamptz) language plpgsql stable security definer set search_path = pg_catalog, private as $$ begin if not private.is_admin() then raise exception 'Administrator access required' using errcode = '42501'; end if; return query select l.id,l.actor_id,l.action,l.target_type,l.target_id,l.details,l.created_at from private.admin_audit_log l order by l.created_at desc limit greatest(1,least(coalesce(p_limit,20),100)); end; $$;
revoke all on function private.admin_overview() from public, anon;
revoke all on function private.admin_recent_activity(integer) from public, anon;
grant execute on function private.admin_overview() to authenticated;
grant execute on function private.admin_recent_activity(integer) to authenticated;
create or replace function public.admin_overview() returns jsonb language sql stable security invoker set search_path = pg_catalog, private as $$ select private.admin_overview(); $$;
create or replace function public.admin_recent_activity(p_limit integer default 20) returns table (id uuid,actor_id uuid,action text,target_type text,target_id uuid,details jsonb,created_at timestamptz) language sql security invoker set search_path = pg_catalog, private as $$ select * from private.admin_recent_activity(p_limit); $$;
revoke all on function public.admin_overview() from public, anon;
revoke all on function public.admin_recent_activity(integer) from public, anon;
grant execute on function public.admin_overview() to authenticated;
grant execute on function public.admin_recent_activity(integer) to authenticated;